async function voidLine(l: { id: string; orderId: string; name: string; qty?: number }) {
  if (isOffline()) { flash(OFFLINE_ORDER_MSG); return; }
  const ok = await confirmAction({
    title: 'Remove Item',
    message: `Remove "${l.name}" from this table? Stock will be restored.`,
    confirmText: 'Remove Item',
    isDestructive: true,
  });
  if (!ok) return;
  setVoidBusyId(l.id);
  try {
    const r = await fetch('/api/tables/order', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ action: 'void_item', orderId: l.orderId, itemId: l.id, ...(l.qty ? { qty: l.qty } : {}) }),
    });
    const d = await r.json();
    if (r.ok) {
      flash(d.cancelled ? 'Item removed · order cancelled' : d.remainingQty !== undefined ? `Quantity reduced · ${d.remainingQty} remaining` : 'Item removed');
      const fresh = await refreshTableOrder();
      refreshTables();
      if (!fresh || fresh.count === 0) closeTableActions(); // table is now empty
    } else flash('Could not remove item');
  } catch { flash('Network error'); }
  finally { setVoidBusyId(null); }
}

interface AggregatedLine {
  key: string;
  name: string;
  itemId?: string | null;
  unitPricePaise: number;
  qty: number;
  linePaise: number;
  station?: string | null;
  kotStatus: string;
  catName?: string;
  subLines: Array<{ id: string; orderId: string; qty: number; linePaise: number; kotStatus: string }>;
}

function aggregateOrderLines(lines: any[]): AggregatedLine[] {
  const map = new Map<string, AggregatedLine>();
  for (const l of lines) {
    const key = `${l.itemId || l.name}__${l.unitPricePaise}`;
    const existing = map.get(key);
    if (!existing) {
      map.set(key, {
        key,
        name: l.name,
        itemId: l.itemId ?? null,
        unitPricePaise: l.unitPricePaise ?? Math.round((l.linePaise || 0) / (l.qty || 1)),
        qty: l.qty,
        linePaise: l.linePaise,
        station: l.station ?? null,
        kotStatus: l.kotStatus || 'in_kitchen',
        catName: l.catName,
        subLines: [{ id: l.id, orderId: l.orderId, qty: l.qty, linePaise: l.linePaise, kotStatus: l.kotStatus }],
      });
    } else {
      existing.qty += l.qty;
      existing.linePaise += l.linePaise;
      if (l.kotStatus === 'in_kitchen' || existing.kotStatus === 'in_kitchen') {
        existing.kotStatus = 'in_kitchen';
      } else if (l.kotStatus === 'ready' || existing.kotStatus === 'ready') {
        existing.kotStatus = 'ready';
      }
      existing.subLines.push({ id: l.id, orderId: l.orderId, qty: l.qty, linePaise: l.linePaise, kotStatus: l.kotStatus });
    }
  }
  return Array.from(map.values());
}

function increaseExistingLine(agg: AggregatedLine) {
  const found = menu.flatMap((c) => c.items.map((it) => ({ ...it, catName: c.name }))).find(
    (it) => (agg.itemId && it.id === agg.itemId) || it.name.trim().toLowerCase() === agg.name.trim().toLowerCase(),
  );
  if (found) {
    addToTable(found);
    flash(`Added 1 "${found.name}" to New Items (unsent)`);
  } else {
    setTableCart((c) => {
      const ex = c.find((l) => (agg.itemId && l.itemId === agg.itemId) || l.name.trim().toLowerCase() === agg.name.trim().toLowerCase());
      if (ex) return c.map((l) => (l.key === ex.key ? { ...l, qty: l.qty + 1 } : l));
      return [...c, {
        key: agg.itemId || agg.name,
        itemId: agg.itemId || agg.name,
        name: agg.name,
        pricePaise: agg.unitPricePaise,
        gstRate: 0,
        station: agg.station || undefined,
        qty: 1,
      }];
    });
    flash(`Added 1 "${agg.name}" to New Items (unsent)`);
  }
}

async function decreaseExistingLine(agg: AggregatedLine) {
  if (!canSettleBill) {
    flash('Modifying sent KOT items requires manager or cashier permission');
    return;
  }
  if (agg.subLines.length === 0) return;
  const targetSub = agg.subLines[agg.subLines.length - 1];
  const isLastTotal = agg.qty <= 1;

  const ok = await confirmAction({
    title: isLastTotal ? 'Remove Item' : 'Decrease Quantity',
    message: isLastTotal
      ? `Remove "${agg.name}" from Table ${tableAction?.label}? Kitchen stock will be restored.`
      : `Reduce "${agg.name}" quantity by 1 on Table ${tableAction?.label}? Kitchen stock will be restored.`,
    confirmText: isLastTotal ? 'Remove Item' : 'Decrease',
    isDestructive: true,
  });
  if (!ok) return;

  setVoidBusyId(targetSub.id);
  try {
    const r = await fetch('/api/tables/order', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        action: 'void_item',
        orderId: targetSub.orderId,
        itemId: targetSub.id,
        qty: 1,
      }),
    });
    const d = await r.json();
    if (r.ok) {
      flash(d.cancelled ? `"${agg.name}" removed · order cancelled` : d.remainingQty !== undefined ? `"${agg.name}" reduced to ${agg.qty - 1}` : `"${agg.name}" removed`);
      const fresh = await refreshTableOrder();
      refreshTables();
      if (!fresh || fresh.count === 0) closeTableActions();
    } else {
      flash('Could not reduce item');
    }
  } catch {
    flash('Network error');
  } finally {
    setVoidBusyId(null);
  }
}

