interface AggregatedLine {
  key: string;
  name: string;
  itemId?: string | null;
  unitPricePaise: number;
  qty: number;
  linePaise: number;
  station?: string | null;
  kotStatus: string;
  catName?: string;
  notes?: string | null;
  subLines: Array<{ id: string; orderId: string; qty: number; linePaise: number; kotStatus: string; notes?: string | null }>;
}

function aggregateOrderLines(lines: any[]): AggregatedLine[] {
  const map = new Map<string, AggregatedLine>();
  for (const l of lines) {
    const key = `${l.itemId || l.name}__${l.unitPricePaise}`;
    const existing = map.get(key);
    if (!existing) {
      map.set(key, {
        key,
        name: l.name,
        itemId: l.itemId ?? null,
        unitPricePaise: l.unitPricePaise ?? Math.round((l.linePaise || 0) / (l.qty || 1)),
        qty: l.qty,
        linePaise: l.linePaise,
        station: l.station ?? null,
        kotStatus: l.kotStatus || 'in_kitchen',
        catName: l.catName,
        notes: l.notes ?? null,
        subLines: [{ id: l.id, orderId: l.orderId, qty: l.qty, linePaise: l.linePaise, kotStatus: l.kotStatus, notes: l.notes ?? null }],
      });
    } else {
      existing.qty += l.qty;
      existing.linePaise += l.linePaise;
      if (l.notes && !existing.notes) existing.notes = l.notes;
      if (l.kotStatus === 'in_kitchen' || existing.kotStatus === 'in_kitchen') {
        existing.kotStatus = 'in_kitchen';
      } else if (l.kotStatus === 'ready' || existing.kotStatus === 'ready') {
        existing.kotStatus = 'ready';
      }
      existing.subLines.push({ id: l.id, orderId: l.orderId, qty: l.qty, linePaise: l.linePaise, kotStatus: l.kotStatus, notes: l.notes ?? null });
    }
  }
  return Array.from(map.values());
}

function increaseExistingLine(agg: AggregatedLine) {
  const found = menu.flatMap((c) => c.items.map((it) => ({ ...it, catName: c.name }))).find(
    (it) => (agg.itemId && it.id === agg.itemId) || it.name.trim().toLowerCase() === agg.name.trim().toLowerCase(),
  );
  if (found) {
    addToTable(found);
    setAddMode(true);
    flash(`Added 1 "${found.name}" to New Items`);
  } else {
    setTableCart((c) => {
      const ex = c.find((l) => (agg.itemId && l.itemId === agg.itemId) || l.name.trim().toLowerCase() === agg.name.trim().toLowerCase());
      if (ex) return c.map((l) => (l.key === ex.key ? { ...l, qty: l.qty + 1 } : l));
      return [...c, {
        key: agg.itemId || agg.name,
        itemId: agg.itemId || agg.name,
